_FULL_MASK = 0x1FF


def _build_units():
    units = []
    for row in range(9):
        units.append([row * 9 + col for col in range(9)])
    for col in range(9):
        units.append([row * 9 + col for row in range(9)])
    for box_row in range(3):
        for box_col in range(3):
            units.append(
                [
                    (box_row * 3 + dr) * 9 + (box_col * 3 + dc)
                    for dr in range(3)
                    for dc in range(3)
                ]
            )
    return units


_UNITS = _build_units()


def _build_peers():
    peers = []
    for cell in range(81):
        related = set()
        for unit in _UNITS:
            if cell in unit:
                related.update(unit)
        related.discard(cell)
        peers.append(sorted(related))
    return peers


_PEERS = _build_peers()


def _propagate(cands):
    """候補のビットマスクを不動点まで絞る。矛盾したら False を返す。"""
    done = [False] * 81
    pending = list(range(81))
    while True:
        # 候補が 1 つのマス（naked single）を確定し、同じ行・列・ブロックから除く
        while pending:
            cell = pending.pop()
            mask = cands[cell]
            if mask == 0:
                return False
            if mask & (mask - 1) or done[cell]:
                continue
            done[cell] = True
            for peer in _PEERS[cell]:
                other = cands[peer]
                if other & mask:
                    other &= ~mask
                    if other == 0:
                        return False
                    cands[peer] = other
                    pending.append(peer)
        # 行・列・ブロックの中で 1 か所にしか入らない数字（hidden single）を確定する
        for unit in _UNITS:
            seen_once = 0
            seen_twice = 0
            for cell in unit:
                mask = cands[cell]
                seen_twice |= seen_once & mask
                seen_once |= mask
            if seen_once != _FULL_MASK:
                return False
            singles = seen_once & ~seen_twice
            if singles:
                for cell in unit:
                    current = cands[cell]
                    forced = current & singles
                    if forced and forced != current:
                        if forced & (forced - 1):
                            return False
                        cands[cell] = forced
                        pending.append(cell)
        if not pending:
            return True


def _search(cands, solutions, limit):
    if not _propagate(cands):
        return
    best_cell = -1
    best_count = 10
    for cell in range(81):
        count = cands[cell].bit_count()
        if 1 < count < best_count:
            best_count = count
            best_cell = cell
            if count == 2:
                break
    if best_cell == -1:
        solutions.append(cands)
        return
    mask = cands[best_cell]
    while mask:
        bit = mask & -mask
        mask ^= bit
        child = cands[:]
        child[best_cell] = bit
        _search(child, solutions, limit)
        if len(solutions) >= limit:
            return


def solve_sudoku(grid: str) -> str:
    if not isinstance(grid, str) or len(grid) != 81:
        raise ValueError("grid must be a string of length 81")
    allowed = "123456789."
    for ch in grid:
        if ch not in allowed:
            raise ValueError("grid contains an invalid character")

    # 確定しているマスどうしの矛盾を調べる
    for unit in _UNITS:
        seen = 0
        for cell in unit:
            ch = grid[cell]
            if ch != ".":
                bit = 1 << (int(ch) - 1)
                if seen & bit:
                    raise ValueError("given digits conflict")
                seen |= bit

    cands = [_FULL_MASK] * 81
    for cell in range(81):
        ch = grid[cell]
        if ch != ".":
            cands[cell] = 1 << (int(ch) - 1)

    solutions = []
    _search(cands, solutions, 2)
    if not solutions:
        raise ValueError("no solution")
    if len(solutions) > 1:
        raise ValueError("multiple solutions")
    solved = solutions[0]
    return "".join(str(mask.bit_length()) for mask in solved)
